m=np.arange(1,361);B0=100000.;r=.08125/12;A=B0*r/(1-(1+r)**-360);bal=B0*(1+r)**m-A*((1+r)**m-1)/r;prev=np.r_[B0,bal[:-1]];interest=r*prev;principal=A-interest;ax.plot(m,interest,label='Scheduled interest',color=ACCENT);ax.plot(m,principal,label='Scheduled principal',color=GOOD);ax.set_xlabel('Month');ax.set_ylabel('USD per $100,000 loan');ax.set_title('Amortisation changes the mix, not the payment',loc='left');ax.legend();ax.grid(alpha=.25)
